mapper.select:
SELECT dk.word   
FROM diary_keyword dk
JOIN diary d ON dk.diary_id = d.id   
WHERE d.user_id = #{userId}   
AND d.is_deleted = 0   
AND DATE(d.created_at) BETWEEN #{start} AND #{end}   
GROUP BY dk.word
ORDER BY COUNT(*) DESC
LIMIT #{limit}

select * from diary
where user_id = #{userId}
and match(content) against(#{keyword} in boolean mode)
order by created_at DESC
limit #{offset},#{pageSize}

select id,content,created_at,mood_type
from diary where user_id = #{userId}
order by created_at DESC
